-- ===================================================
-- URBANOS GESTIÓN INMOBILIARIA - SUPABASE DATABASE SETUP
-- ===================================================

-- 1. Create Agents Table
CREATE TABLE IF NOT EXISTS public.agents (
  id SERIAL PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  role VARCHAR(255) NOT NULL,
  phone VARCHAR(50),
  email VARCHAR(255),
  image TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Create Properties Table
CREATE TABLE IF NOT EXISTS public.properties (
  id INT PRIMARY KEY,
  code VARCHAR(50) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  title VARCHAR(255) NOT NULL,
  commune VARCHAR(100) NOT NULL,
  location VARCHAR(255) NOT NULL,
  address VARCHAR(255),
  price_display VARCHAR(100) NOT NULL,
  price_uf NUMERIC(12,2) DEFAULT 0,
  price_clp NUMERIC(14,2) DEFAULT 0,
  bedrooms INT DEFAULT 0,
  bathrooms INT DEFAULT 0,
  parking INT DEFAULT 0,
  area VARCHAR(50),
  land_area VARCHAR(50),
  is_featured BOOLEAN DEFAULT FALSE,
  operation VARCHAR(50) NOT NULL,
  type VARCHAR(50) NOT NULL,
  image TEXT,
  gallery JSONB DEFAULT '[]'::jsonb,
  description TEXT,
  features JSONB DEFAULT '[]'::jsonb,
  map_coords JSONB DEFAULT '{"lat": -41.4693, "lng": -72.9424}'::jsonb,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Create Leads Contact Table
CREATE TABLE IF NOT EXISTS public.leads (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,
  phone VARCHAR(50),
  message TEXT,
  property_code VARCHAR(50),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. Create Service Orders Table (Orden de venta / Oferta de compra)
CREATE TABLE IF NOT EXISTS public.orders (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  order_type VARCHAR(50) NOT NULL, -- 'captacion' | 'oferta'
  name VARCHAR(255) NOT NULL,
  phone VARCHAR(50) NOT NULL,
  email VARCHAR(255) NOT NULL,
  commune VARCHAR(100),
  operation_type VARCHAR(50),
  property_type VARCHAR(50),
  details TEXT,
  offer_amount VARCHAR(100),
  target_property VARCHAR(255),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS Policies (Allow Public Read & Public Insert for Leads)
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read access for agents" ON public.agents FOR SELECT USING (true);
CREATE POLICY "Allow public read access for properties" ON public.properties FOR SELECT USING (true);
CREATE POLICY "Allow public insert for leads" ON public.leads FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow public insert for orders" ON public.orders FOR INSERT WITH CHECK (true);

-- Populate Agents
ON CONFLICT (id) DO NOTHING;

-- Populate 106 Properties
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  price_display = EXCLUDED.price_display,
  price_uf = EXCLUDED.price_uf,
  price_clp = EXCLUDED.price_clp,
  image = EXCLUDED.image,
  gallery = EXCLUDED.gallery;

-- 5. Create Site Content Table (CMS Real-Time Text Editing)
CREATE TABLE IF NOT EXISTS public.site_content (
  key VARCHAR(255) PRIMARY KEY,
  content TEXT NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read access for site_content" ON public.site_content;
DROP POLICY IF EXISTS "Allow public insert and update for site_content" ON public.site_content;

CREATE POLICY "Allow public read access for site_content" ON public.site_content FOR SELECT USING (true);
CREATE POLICY "Allow public insert and update for site_content" ON public.site_content FOR ALL USING (true);

